"""crossfire.cf_platform — portable helpers generated by Crossfire.

Replacements for Windows-only Python APIs (os.startfile, %APPDATA%, cls...)
that behave the same on Windows, macOS, Linux and FreeBSD.
"""
import os
import subprocess
import sys
import tempfile

IS_WINDOWS = sys.platform == "win32"
IS_MACOS = sys.platform == "darwin"
IS_LINUX = sys.platform.startswith("linux")
IS_FREEBSD = sys.platform.startswith("freebsd")


def platform_name():
    """'windows' | 'macos' | 'linux' | 'freebsd' | sys.platform."""
    if IS_WINDOWS:
        return "windows"
    if IS_MACOS:
        return "macos"
    if IS_LINUX:
        return "linux"
    if IS_FREEBSD:
        return "freebsd"
    return sys.platform


def home_dir():
    return os.path.expanduser("~")


def user_data_dir(local=False):
    """%APPDATA% (or %LOCALAPPDATA%) on Windows, ~/Library/Application Support
    on macOS and $XDG_DATA_HOME or ~/.local/share elsewhere."""
    if IS_WINDOWS:
        key = "LOCALAPPDATA" if local else "APPDATA"
        return os.environ.get(key) or os.path.join(home_dir(), "AppData", "Local" if local else "Roaming")
    if IS_MACOS:
        return os.path.join(home_dir(), "Library", "Application Support")
    return os.environ.get("XDG_DATA_HOME") or os.path.join(home_dir(), ".local", "share")


def user_config_dir():
    if IS_WINDOWS:
        return user_data_dir()
    if IS_MACOS:
        return os.path.join(home_dir(), "Library", "Preferences")
    return os.environ.get("XDG_CONFIG_HOME") or os.path.join(home_dir(), ".config")


def temp_dir():
    return tempfile.gettempdir()


def executable_dir():
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(sys.argv[0] or "."))


def open_path(path):
    """Open a file, folder or URL with the default application (os.startfile)."""
    if IS_WINDOWS:
        os.startfile(path)  # noqa: the only OS where it exists
    elif IS_MACOS:
        subprocess.Popen(["open", str(path)])
    else:
        subprocess.Popen(["xdg-open", str(path)])


def clear_screen():
    """Portable replacement for os.system('cls')."""
    if IS_WINDOWS:
        os.system("cls")
    else:
        sys.stdout.write("\033[2J\033[H")
        sys.stdout.flush()


def getch():
    """Read one key without echo (msvcrt.getwch equivalent), returns str."""
    if IS_WINDOWS:
        import msvcrt
        return msvcrt.getwch()
    import termios
    import tty
    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    try:
        tty.setraw(fd)
        return sys.stdin.read(1)
    finally:
        termios.tcsetattr(fd, termios.TCSADRAIN, old)


def kbhit():
    """True when a key press is waiting (msvcrt.kbhit equivalent)."""
    if IS_WINDOWS:
        import msvcrt
        return msvcrt.kbhit()
    import select
    return bool(select.select([sys.stdin], [], [], 0)[0])
